interface Descritivel {
  descrever(): string;
}
abstract class Conta implements Descritivel {
  static criadas = 0;
  #saldo = 0;
  constructor(public readonly titular: string, protected taxa: number) {
    Conta.criadas++;
  }
  get saldo(): number { return this.#saldo; }
  depositar(valor: number): this {
    this.#saldo += valor - this.taxa;
    return this;
  }
  abstract tipo(): string;
  descrever(): string {
    return `${this.tipo()} de ${this.titular}: ${this.saldo}`;
  }
}
class ContaOrdem extends Conta {
  constructor(titular: string) { super(titular, 1); }
  override tipo(): string { return "Conta à ordem"; }
}

