interface Utilizador { id: number; nome: string }

function eUtilizador(v: unknown): v is Utilizador {
  return typeof v === "object" && v !== null &&
    "id" in v && typeof v.id === "number" &&
    "nome" in v && typeof v.nome === "string";
}
type Resultado<T, E> = { ok: true; valor: T } | { ok: false; erro: E };

function lerUtilizador(texto: string): Resultado<Utilizador, string> {
  try {
    const dados: unknown = JSON.parse(texto);   // JSON.parse devolve any
    return eUtilizador(dados) ? { ok: true, valor: dados } : { ok: false, erro: "forma inválida" };
  } catch (e) {                                 // e: unknown
    return { ok: false, erro: e instanceof Error ? e.message : String(e) };
  }
}
async function obterNome(texto: string): Promise<string> {
  const r = lerUtilizador(texto);
  return r.ok ? r.valor.nome : `erro: ${r.erro}`;
}
const config = { porta: 8080, modo: "dev" } satisfies Record<string, string | number>;

