interface Produto {
  readonly id: number;
  nome: string;
  preco: number;
  stock?: number;
}
type ResumoProduto = Pick<Produto, "id" | "nome">;

function valorEmStock(produtos: readonly Produto[]): number {
  return produtos.reduce((total, p) => total + p.preco * (p.stock ?? 0), 0);
}
function resumir(p: Produto): ResumoProduto {
  return { id: p.id, nome: p.nome };
}

const catalogo: readonly Produto[] = [
  { id: 1, nome: "Caneta", preco: 1.5, stock: 10 },
  { id: 2, nome: "Caderno", preco: 3, stock: 4 },
  { id: 3, nome: "Régua", preco: 2 },
];
console.log(valorEmStock(catalogo));               // 27
console.log(catalogo.map(resumir).map((r) => r.nome)); // [ 'Caneta', 'Caderno', 'Régua' ]

type Pagamento =
  | { metodo: "mbway"; telemovel: string }
  | { metodo: "cartao"; ultimos4: string }
  | { metodo: "multibanco"; entidade: number; referencia: string };

function casoImpossivel(valor: never): never {
  throw new Error(`Método não tratado: ${JSON.stringify(valor)}`);
}
function descrever(p: Pagamento): string {
  switch (p.metodo) {
    case "mbway": return `MB WAY para ${p.telemovel}`;
    case "cartao": return `Cartão terminado em ${p.ultimos4}`;
    case "multibanco": return `Entidade ${p.entidade}, ref. ${p.referencia}`;
    default: return casoImpossivel(p);
  }
}
function eMbway(p: Pagamento): p is Extract<Pagamento, { metodo: "mbway" }> {
  return p.metodo === "mbway";
}

const lista: Pagamento[] = [
  { metodo: "mbway", telemovel: "912345678" },
  { metodo: "cartao", ultimos4: "4321" },
  { metodo: "multibanco", entidade: 12345, referencia: "123 456 789" },
];
console.log(lista.map(descrever)[2]);                     // Entidade 12345, ref. 123 456 789
console.log(lista.filter(eMbway).map((p) => p.telemovel)); // [ '912345678' ]

type Igual<A, B> =
  (<T>() => T extends A ? 1 : 2) extends (<T>() => T extends B ? 1 : 2) ? true : false;
type Esperar<T extends true> = T;

type ProfundoLeitura<T> = T extends (...args: any[]) => any
  ? T
  : { readonly [K in keyof T]: ProfundoLeitura<T[K]> };

type Ouvintes<T> = {
  [K in keyof T as `on${Capitalize<string & K>}Mudou`]: (novo: T[K]) => void;
};

